export type IconName = keyof typeof GLYPHS

/**
 * A small solid icon in currentColor. `stroke` and `filled` are accepted for
 * upstream compatibility; Heroicons solid glyphs are always filled.
 */
export function Icon({ name, size = 16, className, style }: { name: IconName; size?: number; stroke?: number; filled?: boolean; className?: string; style?: CSSProperties }) {
  return (
    <svg viewBox="0 0 16 16" width={size} height={size} className={`ss-icon${className ? ` ${className}` : ""}`} style={style} aria-hidden fill="currentColor">
      {(GLYPHS[name] as Glyph).map((p, i) => (
        <path key={i} d={p.d} fillRule={p.evenodd ? "evenodd" : undefined} clipRule={p.evenodd ? "evenodd" : undefined} />
      ))}
    </svg>
  )
}
